"""Checks on the corpus generated by scripts/prepare_corpus.py."""
import json
from collections import Counter
from pathlib import Path

import pytest
import yaml

from rag.chunking import chunk_document
from rag.documents import load_corpus

DATA = Path(__file__).resolve().parents[2] / "data"


@pytest.fixture(scope="module")
def docs():
    return {d.doc_id: d for d in load_corpus(DATA / "corpus")}


@pytest.fixture(scope="module")
def base(docs):
    return [d for d in docs.values() if d.doc_id.count("-") == 1]


@pytest.fixture(scope="module")
def golden():
    return [json.loads(line) for line in (DATA / "golden.jsonl").read_text().splitlines()]


def test_96_base_docs(base):
    assert len(base) == 96
    assert Counter(d.lang for d in base) == {"en": 48, "ru": 48}


def test_240_paragraphs_per_language_matching_one_to_one(base):
    ids = {lang: sorted(p.id for d in base if d.lang == lang for p in d.paragraphs) for lang in ("en", "ru")}
    assert len(ids["en"]) == len(set(ids["en"])) == 240
    assert ids["en"] == ids["ru"]


def test_every_doc_has_acl(docs):
    assert all(d.acl for d in docs.values())
    groups = Counter(tuple(d.acl) for d in docs.values())
    assert groups[("hr-team",)] > 0 and groups[("research",)] > 0


def test_superseded_copies(docs):
    old = [d for d in docs.values() if d.doc_id.endswith("-old")]
    assert old
    for d in old:
        current = docs[d.superseded_by]
        assert d.status == "archived" and current.status == "active"
        assert d.updated_at < current.updated_at
        diffs = [a for a, b in zip(d.paragraphs, current.paragraphs) if a.text != b.text]
        assert len(diffs) == 1


def test_informal_copies_contradict_one_paragraph(docs):
    slack = [d for d in docs.values() if d.doc_id.endswith("-slack")]
    assert slack
    for d in slack:
        assert d.source == "slack" and d.authority == "informal"
        (p,) = d.paragraphs
        original = next(q for q in docs[d.doc_id.removesuffix("-slack")].paragraphs if p.id.startswith(q.id))
        assert p.text != original.text


def test_copies_are_not_gold(docs, golden):
    copy_pids = {p.id for d in docs.values() if d.doc_id.count("-") > 1 for p in d.paragraphs}
    assert copy_pids
    assert not copy_pids & {g["gold_paragraph"] for g in golden}


def test_golden_kinds(golden):
    kinds = Counter(g["kind"] for g in golden)
    assert kinds["answerable"] == 2 * 1190
    assert kinds["unanswerable"] >= 30
    assert kinds["acl"] > 0
    assert sum("generation" in g["tags"] for g in golden) == 60


def test_acl_cases_target_docs_alice_cannot_see(docs, golden):
    users = yaml.safe_load((DATA / "users.yaml").read_text())
    for g in golden:
        if g["kind"] == "acl":
            assert not set(docs[g["gold_doc"]].acl) & set(users[g["user"]])


def test_every_paragraph_is_covered_by_a_chunk(docs, config):
    def words(text):
        return len(text.split())

    for d in docs.values():
        chunks = chunk_document(d, words, config.chunking.max_tokens, config.chunking.overlap)
        assert {p.id for p in d.paragraphs} == {pid for c in chunks for pid in c.paragraph_ids}
        assert all(c.lang == d.lang for c in chunks)
